impl From<u16> for Kotlin {
    #[inline(always)]
    fn from(x: u16) -> Self {
        num::FromPrimitive::from_u16(x).unwrap_or(Self::Error)
    }
}

// Kotlin == u16
impl PartialEq<u16> for Kotlin {
    #[inline(always)]
    fn eq(&self, x: &u16) -> bool {
        *self == Into::<Self>::into(*x)
    }
}

// u16 == Kotlin
impl PartialEq<Kotlin> for u16 {
    #[inline(always)]
    fn eq(&self, x: &Kotlin) -> bool {
        *x == *self
    }
}
